// This file is mechanically ported from the Dart package language tables.
// Keep aliases in source order: the first value is used for localized formatting.

use crate::{book::Book, language::Language};

/// Bundled localized names and abbreviations for one Bible book.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct LocalizedBook {
    pub(crate) book: Book,
    pub(crate) names: &'static [&'static str],
    pub(crate) abbreviations: &'static [&'static str],
}

impl LocalizedBook {
    /// Return the book described by this record.
    #[must_use]
    pub const fn book(self) -> Book {
        self.book
    }

    /// Return every bundled localized long-name alias in source order.
    #[must_use]
    pub const fn names(self) -> &'static [&'static str] {
        self.names
    }

    /// Return every bundled localized abbreviation in source order.
    #[must_use]
    pub const fn abbreviations(self) -> &'static [&'static str] {
        self.abbreviations
    }

    pub(crate) fn all_aliases(self) -> impl Iterator<Item = &'static str> {
        self.names.iter().chain(self.abbreviations).copied()
    }
}

/// Returns the bundled localized records for a concrete language.
#[must_use]
pub const fn localized_books(language: Language) -> Option<&'static [LocalizedBook]> {
    match language {
        Language::Arabic => Some(&ARABIC_BOOKS),
        Language::Chinese => Some(&CHINESE_BOOKS),
        Language::French => Some(&FRENCH_BOOKS),
        Language::German => Some(&GERMAN_BOOKS),
        Language::Hebrew => Some(&HEBREW_BOOKS),
        Language::Hindi => Some(&HINDI_BOOKS),
        Language::Indonesian => Some(&INDONESIAN_BOOKS),
        Language::Korean => Some(&KOREAN_BOOKS),
        Language::Portuguese => Some(&PORTUGUESE_BOOKS),
        Language::Russian => Some(&RUSSIAN_BOOKS),
        Language::Spanish => Some(&SPANISH_BOOKS),
        Language::Tagalog => Some(&TAGALOG_BOOKS),
        _ => None,
    }
}

/// Alias for [`localized_books`] used by parser construction.
#[must_use]
pub(crate) const fn aliases(language: Language) -> Option<&'static [LocalizedBook]> {
    localized_books(language)
}

/// Returns a preferred bundled name without applying an English fallback.
#[must_use]
pub fn localized_name(book: Book, language: Language, short: bool) -> Option<&'static str> {
    match language {
        Language::Auto | Language::English => Some(if short {
            book.abbreviation()
        } else {
            book.full_name()
        }),
        _ => localized_books(language)
            .and_then(|books| books.iter().find(|entry| entry.book == book))
            .and_then(|entry| preferred_name(*entry, short)),
    }
}

fn preferred_name(entry: LocalizedBook, short: bool) -> Option<&'static str> {
    let terms = if short {
        entry.abbreviations
    } else {
        entry.names
    };
    let non_empty = || terms.iter().copied().filter(|term| !term.trim().is_empty());

    if short {
        non_empty().reduce(|shortest, candidate| {
            if candidate.chars().count() < shortest.chars().count() {
                candidate
            } else {
                shortest
            }
        })
    } else {
        non_empty().next()
    }
}

/// Returns the preferred long book name, falling back to English.
#[must_use]
pub fn long_name(book: Book, language: Language) -> &'static str {
    localized_name(book, language, false).unwrap_or_else(|| book.full_name())
}

/// Returns the preferred compact book abbreviation, falling back to English.
#[must_use]
pub fn short_name(book: Book, language: Language) -> &'static str {
    localized_name(book, language, true).unwrap_or_else(|| book.abbreviation())
}

